package com.vityarthi.library.repository;
import com.vityarthi.library.db.Database; import com.vityarthi.library.model.Reservation; import java.sql.*; import java.time.*; import java.util.*;
public class ReservationRepository {
 public long insert(Reservation r){String q="INSERT INTO reservations(book_id,member_id,priority,reserved_at,status) VALUES(?,?,?,?,?)";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setLong(1,r.getBookId());p.setLong(2,r.getMemberId());p.setInt(3,r.getPriority());p.setString(4,r.getReservedAt().toString());p.setString(5,r.getStatus());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){return k.next()?k.getLong(1):0;}}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean waiting(long book,long member){try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT 1 FROM reservations WHERE book_id=? AND member_id=? AND status='WAITING'")){p.setLong(1,book);p.setLong(2,member);try(ResultSet r=p.executeQuery()){return r.next();}}catch(SQLException e){throw new IllegalStateException(e);}}
 public List<Reservation> waitingFor(long book){List<Reservation>x=new ArrayList<>();String q="SELECT * FROM reservations WHERE book_id=? AND status='WAITING' ORDER BY priority DESC,reserved_at,id";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,book);try(ResultSet r=p.executeQuery()){while(r.next())x.add(map(r));return x;}}catch(SQLException e){throw new IllegalStateException(e);}}
 public void ready(long id){try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("UPDATE reservations SET status='READY' WHERE id=?")){p.setLong(1,id);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}
 public List<Reservation> allWaiting(){List<Reservation>x=new ArrayList<>();try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT * FROM reservations WHERE status='WAITING' ORDER BY book_id,priority DESC,reserved_at,id");ResultSet r=p.executeQuery()){while(r.next())x.add(map(r));return x;}catch(SQLException e){throw new IllegalStateException(e);}}
 private Reservation map(ResultSet r)throws SQLException{return new Reservation(r.getLong("id"),r.getLong("book_id"),r.getLong("member_id"),r.getInt("priority"),LocalDateTime.parse(r.getString("reserved_at")),r.getString("status"));}
}